import{_ as d,o as a,c as e,ah as r}from"./chunks/framework.DuX8SFU5.js";const p=JSON.parse('{"title":"AM_CAN_LOGGER — даташит","description":"","frontmatter":{"title":"AM_CAN_LOGGER — даташит","pdf":"/pdf/AM_CAN_LOGGER_datasheet.pdf","pdfStyle":"datasheet","pageClass":"datasheet-page","preliminary":true},"headers":[],"relativePath":"am_can_logger/datasheet.md","filePath":"am_can_logger/datasheet.md"}'),o={name:"am_can_logger/datasheet.md"};function l(h,t,c,i,n,s){return a(),e("div",null,[...t[0]||(t[0]=[r('<h2 id="_1-описание" tabindex="-1">1. Описание <a class="header-anchor" href="#_1-описание" aria-label="Permalink to &quot;1. Описание&quot;">​</a></h2><p>AM_CAN_LOGGER — автономный регистратор CAN-трафика и вибраций на базе полётного контроллера Pixhawk 6X (FMUv6X) с прошивкой на основе PX4. Он слушает две шины CAN, не передавая в них ничего, и записывает каждый кадр с меткой времени на карту microSD; при выгрузке запись превращается в формат <code>candump</code>. Параллельно в журнал ULog пишутся состояние регистратора и, по выбору, сырые данные акселерометра и гироскопа с полной частотой датчика. Прошивка запускает только то, что нужно регистратору, без оценки положения, регуляторов и навигации полётного контроллера: освободившаяся память идёт под буфер записи.</p><h2 id="_2-возможности" tabindex="-1">2. Возможности <a class="header-anchor" href="#_2-возможности" aria-label="Permalink to &quot;2. Возможности&quot;">​</a></h2><ul><li>Две шины CAN, скорость каждой задаётся отдельно, от 10 кбит/с до 1 Мбит/с, или определяется автоматически.</li><li>Режим только приёма: контроллер CAN не подтверждает кадры и не выдаёт ошибок; автоподбор скорости тоже ничего не передаёт.</li><li>Метка времени ставится в прерывании приёма кадра, с разрешением 1 мкс.</li><li>Компактная двоичная запись, около 16 байт на кадр против около 48 в тексте <code>candump</code>; новый файл каждые 10 минут. Текст <code>candump -L</code> прямо на карту включается параметром.</li><li>Места и число потерянных кадров отмечаются в самой записи.</li><li>Сырые данные акселерометра и гироскопа в ULog для анализа вибраций.</li><li>Автозапуск при подаче питания, запись с момента загрузки.</li><li>Счётчики кадров и потерь по каждой шине, раз в секунду в ULog.</li><li>Текстовые отметки событий в отдельном файле рядом с записью и в ULog.</li><li>Индикация состояния светодиодом.</li><li><a href="./dashboard">Веб-панель</a> по USB: состояние, графики загрузки шин и карты, выгрузка и удаление файлов, настройки, разбор протоколов DroneCAN, CANopen и J1939, живой поток кадров для DroneCAN GUI Tool.</li></ul><h2 id="_3-характеристики" tabindex="-1">3. Характеристики <a class="header-anchor" href="#_3-характеристики" aria-label="Permalink to &quot;3. Характеристики&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Параметр</th><th>Мин.</th><th>Тип.</th><th>Макс.</th><th>Ед.</th><th>Примечание</th></tr></thead><tbody><tr><td>Число шин CAN</td><td>—</td><td>2</td><td>2</td><td></td><td>CAN1 и CAN2 контроллера</td></tr><tr><td>Скорость шины</td><td>10</td><td>—</td><td>1000</td><td>кбит/с</td><td>Для каждой шины своя</td></tr><tr><td>Скорости автоподбора</td><td></td><td></td><td></td><td>кбит/с</td><td>10, 20, 50, 125, 250, 500, 800, 1000</td></tr><tr><td>Время автоподбора</td><td>—</td><td>1</td><td>—</td><td>с</td><td>Измерено на стенде</td></tr><tr><td>Формат кадров</td><td></td><td></td><td></td><td></td><td>Классический CAN, 11 и 29 бит; CAN FD не поддерживается</td></tr><tr><td>Разрешение метки времени</td><td>—</td><td>1</td><td>—</td><td>мкс</td><td></td></tr><tr><td>Запись на карту на кадр</td><td>15</td><td>16</td><td>17</td><td>Б</td><td>Двоичный формат; в тексте <code>candump</code> около 48</td></tr><tr><td>Пропускная способность записи без потерь, пачка</td><td>—</td><td>—</td><td>10,5</td><td>тыс. кадр/с</td><td>2 с, измерено на стенде</td></tr><tr><td>Потери за 50 ч записи, 3,7 тыс. кадр/с</td><td>—</td><td>0,006</td><td>—</td><td>%</td><td>Две шины, 1 Мбит/с и 500 кбит/с, стенд</td></tr><tr><td>Длительность файла</td><td>0</td><td>600</td><td>3600</td><td>с</td><td>0 — без деления на файлы</td></tr><tr><td>Буфер между приёмом и картой</td><td>4</td><td>320</td><td>512</td><td>КиБ</td><td>Размер, который не помещается в память, уменьшается вдвое</td></tr><tr><td>Синхронизация файла на карту</td><td>—</td><td>1</td><td>—</td><td>с</td><td></td></tr><tr><td>Частота записи IMU</td><td>—</td><td>400</td><td>—</td><td>сообщ./с</td><td>Пакеты отсчётов с полной частотой датчика</td></tr><tr><td>Объём записи при 3,7 тыс. кадр/с</td><td>—</td><td>0,2</td><td>—</td><td>ГБ/ч</td><td>Измерено за 50 ч</td></tr><tr><td>Выгрузка по USB</td><td>—</td><td>0,5</td><td>—</td><td>МБ/с</td><td></td></tr></tbody></table><p>Предел записи — карта памяти, а не приём кадров. Время от времени карта останавливает запись на несколько секунд для внутреннего обслуживания (на стенде — до 6,6 с), и буфер должен перекрыть такую остановку на текущем потоке: 320 КиБ при 60 КиБ/с хватает примерно на 5 с. Все потери за 50 часов на стенде — переполнения буфера во время таких остановок. Сырые данные IMU добавляют к потоку на карту около 200 КиБ/с, поэтому при плотном CAN-потоке их стоит выключать.</p><h2 id="_4-подключение" tabindex="-1">4. Подключение <a class="header-anchor" href="#_4-подключение" aria-label="Permalink to &quot;4. Подключение&quot;">​</a></h2><h3 id="_4-1-разъемы-can1-и-can2" tabindex="-1">4.1. Разъёмы CAN1 и CAN2 <a class="header-anchor" href="#_4-1-разъемы-can1-и-can2" aria-label="Permalink to &quot;4.1. Разъёмы CAN1 и CAN2&quot;">​</a></h3><p>JST-GH, 4 контакта, по стандарту разъёмов Pixhawk:</p><table tabindex="0"><thead><tr><th>Конт.</th><th>Сигнал</th></tr></thead><tbody><tr><td>1</td><td>5 В</td></tr><tr><td>2</td><td>CAN_H</td></tr><tr><td>3</td><td>CAN_L</td></tr><tr><td>4</td><td>GND</td></tr></tbody></table><p>Контакт 5 В к шине машины не подключается.</p><h3 id="_4-2-питание" tabindex="-1">4.2. Питание <a class="header-anchor" href="#_4-2-питание" aria-label="Permalink to &quot;4.2. Питание&quot;">​</a></h3><p>Контроллер питается через модуль питания на разъём POWER; от бортовой сети 24 В питание подаётся через преобразователь и предохранитель.</p><h2 id="_5-данные-на-карте" tabindex="-1">5. Данные на карте <a class="header-anchor" href="#_5-данные-на-карте" aria-label="Permalink to &quot;5. Данные на карте&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Путь</th><th>Содержимое</th></tr></thead><tbody><tr><td><code>log/&lt;дата&gt;/&lt;время&gt;_can_NNNN.amcan</code></td><td>CAN-кадры; новый файл каждые 10 минут</td></tr><tr><td><code>log/&lt;дата&gt;/&lt;время&gt;_events.log</code></td><td>Отметки событий</td></tr><tr><td><code>log/&lt;дата&gt;/&lt;время&gt;.ulg</code></td><td>ULog: состояние регистратора, по выбору — IMU</td></tr></tbody></table><p>Запись CAN лежит в папке журнала ULog той же сессии; пока часы контроллера не выставлены, папка называется <code>sessNNN</code>. Если журнал ULog не ведётся, запись лежит в <code>candump/sessNNN/</code>. Автоматическая очистка старых сессий (нехватка места, параметр <code>SDLOG_DIRS_MAX</code>) удаляет запись CAN вместе с её журналом.</p><p>Двоичная запись начинается с заголовка, в котором указаны скорость и протокол каждой шины. Дальше идут кадры, метки абсолютного времени в начале и каждые 100 мс и записи о потерях с числом потерянных кадров. Панель выгружает её в формате <code>candump</code>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(1712345678.123456) can0 18EEFF01#0102030405060708</span></span></code></pre></div><p><code>can0</code> — шина CAN1, <code>can1</code> — шина CAN2. Время в скобках — секунды и микросекунды по часам контроллера. Отметки событий записаны на тех же часах; в скобках — имя, если оно задано в панели:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(1712345678.123456) начало бурения [Оператор]</span></span></code></pre></div><h2 id="_6-параметры" tabindex="-1">6. Параметры <a class="header-anchor" href="#_6-параметры" aria-label="Permalink to &quot;6. Параметры&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Параметр</th><th>По умолчанию</th><th>Назначение</th></tr></thead><tbody><tr><td><code>SYS_AUTOSTART</code></td><td>22001</td><td>Конфигурация регистратора: запускает только то, что ему нужно</td></tr><tr><td><code>CANLOG_EN</code></td><td>1</td><td>Запуск регистратора при загрузке</td></tr><tr><td><code>CANLOG_BITRATE1</code></td><td>1000000</td><td>Скорость шины CAN1, бит/с; 0 — определять автоматически</td></tr><tr><td><code>CANLOG_BITRATE2</code></td><td>1000000</td><td>Скорость шины CAN2, бит/с; 0 — определять автоматически</td></tr><tr><td><code>CANLOG_PROTO1</code></td><td>0</td><td>Протокол шины CAN1 для разбора в панели: 0 — определять, 1 — DroneCAN, 2 — CANopen, 3 — J1939</td></tr><tr><td><code>CANLOG_PROTO2</code></td><td>0</td><td>То же для шины CAN2</td></tr><tr><td><code>CANLOG_IFACES</code></td><td>3</td><td>Маска шин: бит 0 — CAN1, бит 1 — CAN2</td></tr><tr><td><code>CANLOG_SILENT</code></td><td>1</td><td>Только приём</td></tr><tr><td><code>CANLOG_ROT_S</code></td><td>600</td><td>Длительность файла, с; 0 — не делить</td></tr><tr><td><code>CANLOG_BUF_KB</code></td><td>320</td><td>Буфер между приёмом и картой, КиБ</td></tr><tr><td><code>CANLOG_FORMAT</code></td><td>1</td><td>1 — двоичная запись (<code>.amcan</code>), 0 — текст <code>candump</code> (<code>.log</code>)</td></tr><tr><td><code>UAVCAN_ENABLE</code></td><td>0</td><td>Должен быть 0: регистратор сам управляет контроллером CAN</td></tr><tr><td><code>SDLOG_MODE</code></td><td>2</td><td>Журнал ULog с момента загрузки</td></tr><tr><td><code>SDLOG_PROFILE</code></td><td>4096</td><td>Только состояние регистратора, около 2 КиБ/с; 4864 — плюс сырые данные IMU; 1 — полный журнал PX4, около 40 КиБ/с; 769 — полный плюс IMU</td></tr></tbody></table><p>Значения по умолчанию даны для конфигурации 22001; значения, уже сохранённые на контроллере, она не меняет. Изменения вступают в силу после перезагрузки.</p><h2 id="_7-индикация" tabindex="-1">7. Индикация <a class="header-anchor" href="#_7-индикация" aria-label="Permalink to &quot;7. Индикация&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Состояние</th><th>Условие</th><th>Светодиод контроллера</th><th>Внешний RGB-светодиод</th></tr></thead><tbody><tr><td>Запись</td><td>Все включённые шины передали кадры за последние 2 с, потерь нет</td><td>1 Гц</td><td>зелёный, медленно</td></tr><tr><td>Тишина на шине</td><td>Одна из шин молчит дольше 2 с</td><td>короткая вспышка раз в 2 с</td><td>жёлтый, медленно</td></tr><tr><td>Потери</td><td>Потеря кадра или ошибка записи за последние 5 с, либо файл не открыт</td><td>5 Гц</td><td>красный, часто</td></tr></tbody></table><h2 id="_8-диагностика" tabindex="-1">8. Диагностика <a class="header-anchor" href="#_8-диагностика" aria-label="Permalink to &quot;8. Диагностика&quot;">​</a></h2><p>Регистратор раз в секунду публикует своё состояние: поток и загрузку каждой шины, запись на карту, потери по причинам, самую долгую операцию карты, загрузку процессора, память и температуру. Его показывает панель, оно же пишется в ULog, а команда <code>can_logger status</code> в консоли контроллера выводит его текстом. Потери разделены на две причины: переполнение буфера означает, что карта не успевает, переполнение очереди драйвера — что задача приёма не успела её вычитать. Доля потерь считается от всех кадров на шине, включая те, что драйвер потерял до регистратора.</p><h2 id="_9-известные-ограничения" tabindex="-1">9. Известные ограничения <a class="header-anchor" href="#_9-известные-ограничения" aria-label="Permalink to &quot;9. Известные ограничения&quot;">​</a></h2><ul><li>Две шины на устройство; для третьей нужен второй регистратор или внешний контроллер CAN.</li><li>Гальванической развязки CAN нет.</li><li>Без внешнего источника времени часы после каждого включения начинаются с 2000-01-01, пока их не выставит панель; интервалы между кадрами точные.</li><li>Остановки карты длятся до нескольких секунд; при плотном потоке самая длинная может стоить пачки кадров.</li><li>Файлы выгружаются по одному: PX4 ведёт один сеанс передачи файлов, и передача из QGroundControl по тому же каналу прерывает выгрузку панели.</li><li>Сжатия сверх двоичного формата нет.</li><li>Схемы мигания светодиода предварительные.</li></ul><h2 id="_10-история-документа" tabindex="-1">10. История документа <a class="header-anchor" href="#_10-история-документа" aria-label="Permalink to &quot;10. История документа&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Версия</th><th>Дата</th><th>Изменения</th></tr></thead><tbody><tr><td>0.1</td><td>2026-10-01</td><td>Первая редакция даташита</td></tr><tr><td>0.2</td><td>2026-10-05</td><td>Автоподбор скорости, двоичная запись, отметки событий, состояние в ULog, веб-панель, конфигурация 22001; потери за 50 ч на стенде</td></tr></tbody></table>',32)])])}const N=d(o,[["render",l]]);export{p as __pageData,N as default};
